#!/usr/bin/env python3
"""Record exact native PCB/DRC/rule hashes after native checks. No checks are faked."""
import json,hashlib,datetime,collections
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def iso(ts):return datetime.datetime.fromtimestamp(ts,datetime.timezone.utc).isoformat()
def main():
    out={'revision':'A5','recorded_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'native_tool':'KiCad10.0.8-10.0.8~ubuntu24.04.1','hardware_tests':'NOT_RUN','manufacturing_release':False,'boards':[],'custom_drc_exclusions':[],'exclusion_note':'No DRC exclusion entries or custom rule suppression added. Project files contain stated clearances; native default severities otherwise apply. Unconnected items are counted separately from violation list. Native ERC and independent exported-netlist checks are recorded by the package integration reports.'}
    for name in ['controller','led_leaf','power_adapter']:
        board=ROOT/'native'/name/(name+'.kicad_pcb');pro=board.with_suffix('.kicad_pro');report=ROOT/'reports'/(name+'_drc.json');d=json.loads(report.read_text());settings=json.loads(pro.read_text())
        vs=d['violations'];unc=d.get('unconnected_items',[])
        out['boards'].append({'name':name,'pcb':str(board.relative_to(ROOT)),'pcb_sha256':sha(board),'project':str(pro.relative_to(ROOT)),'project_sha256':sha(pro),'drc_report':str(report.relative_to(ROOT)),'drc_report_sha256':sha(report),'drc_report_written_utc':iso(report.stat().st_mtime),'violation_count':len(vs),'violations_by_type':dict(collections.Counter(x['type'] for x in vs)),'unconnected_count':len(unc),'rules':settings.get('board',{}).get('design_settings',{}),'net_settings':settings.get('net_settings',{}),'release_status':'CONTROLLER_UNROUTED' if name=='controller' else 'ROUTED_DRC_CLEAN_ENGINEERING_PROTOTYPE','specific_limits':[f'{len(unc)} unconnected items; no copper routes or planes; power/bypass/layout not qualified','Two retained courtyard-projection conflicts: J3 versus raised/insulated H1 screw head, and J3 versus C7. Actual mated plug, solder height, clamp relief and manufacturing tolerance remain qualification gates.','Controller J4 removed. A single controller header carries independent DATA_L/DATA_R; two-port identical leaves pass the streams through with a pin3/4 swap. Two straight1:1 completed cables remain. First cable and first-leaf rails carry both leaves.','SWD row relocated to rear globalY80.7 with four resistors in the freed J4 area. Fixture and optical-removal access still require qualification.'] if name=='controller' else ['Mechanical/mating/terminal-trim/tolerance and factory review remain; electrical DRC does not establish complete module fit.']})
    out['footprint_library']=[{'path':str(p.relative_to(ROOT)),'sha256':sha(p)} for p in sorted((ROOT/'footprints').rglob('*')) if p.is_file()]
    out['authoritative_inputs']=[{'path':str(p.relative_to(ROOT)),'sha256':sha(p)} for p in [ROOT/'design'/'design_data.py',ROOT/'design'/'generate_electronics.py',ROOT/'design'/'controller_placement_override.json',ROOT/'fitted_component_ledger.json',ROOT/'placement_and_connectivity.json']]
    out['qualification_gates']=['Complete controller routing and power/ground return paths; short buckVIN/SW/BST/FB/ground loops and device-local bypasses; rerunDRC with zero unconnected','Native schematic/PCB roundtrip and complete factoryBOM/CPL/panelization review','Samsung/Yageo MLCC operating capacitance versus bias/tolerance/temperature/ageing; no minimum effectiveC proof yet','TPS2552-1 fault/reset/thermal behavior and firmware reset retention on real rails','U7 partial-supply/differential-input/transient/LDOreverse-current bounds; full power sequencing remains unqualified','AP63205/TDK hot-short/startup/current-limit/overshoot waveforms and enclosure heating','Exact incoming WS2812B-2020-V6 revision and measured pulse timings; StandardPCBA/MSL5 handling','Incoming jack contact continuity, switch throw direction, harness continuity and polarity','Physical controller support, bridge-cable bend/sample fit, rear SWD access, mated envelopes, tail trimming and depth']
    dest=ROOT/'reports'/'pcb_qualification.json';dest.write_text(json.dumps(out,indent=2)+'\n');print(dest)
if __name__=='__main__':main()
